import {transitionLook} from './transition-look.mjs';
// Development-only recording of the actual video and live renderer, never generated gameplay.
export class CinematicRecorder{
 constructor(world,director,host){Object.assign(this,{world,director,host});}
 start(){this.stop();if(this.director.stage==='video'&&this.director.video.readyState<2){this.awaiting=()=>{this.awaiting=null;this.start();};this.director.video.addEventListener('loadeddata',this.awaiting,{once:true});return;}if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)return;const source=this.world.renderer.domElement;this.canvas=document.createElement('canvas');this.canvas.width=source.width;this.canvas.height=source.height;this.ctx=this.canvas.getContext('2d');this.chunks=[];this.stream=this.canvas.captureStream(24);this.recorder=new MediaRecorder(this.stream,{mimeType:MediaRecorder.isTypeSupported('video/webm;codecs=vp9')?'video/webm;codecs=vp9':'video/webm',videoBitsPerSecond:2500000});const chunks=this.chunks;this.recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};this.recorder.onstop=()=>{const a=document.createElement('a');a.download=this.director.stage==='off'?'DrillRun_Premium_Jugable.webm':'DrillRun_Transicion_CamaraB.webm';a.textContent='Descargar demostración visual (sin audio)';a.href=URL.createObjectURL(new Blob(chunks,{type:'video/webm'}));a.id='cinemaDownload';this.host.querySelector('#cinemaDownload')?.remove();this.host.append(a);this.stream.getTracks().forEach(t=>t.stop());};this.recorder.start();this.timer=setInterval(()=>this.draw(),1000/24);this.draw();}
 draw(){const ctx=this.ctx;if(!ctx)return;const w=this.canvas.width,h=this.canvas.height,d=this.director,v=d.video;ctx.drawImage(this.world.renderer.domElement,0,0,w,h);if(['video','transform'].includes(d.stage)&&v.readyState>=2){ctx.save();const p=d.stage==='transform'?d.progress:0,fx=transitionLook(p),edge=fx.edge/100;ctx.globalAlpha=fx.opacity;ctx.beginPath();ctx.rect(0,0,Math.max(0,w*(edge+.03)),h);ctx.clip();ctx.fillStyle='#243944';ctx.fillRect(0,0,w,h);const k=Math.max(w/v.videoWidth,h/v.videoHeight),vw=v.videoWidth*k,vh=v.videoHeight*k;ctx.drawImage(v,(w-vw)/2+fx.shift,(h-vh)/2,vw,vh);ctx.restore();if(d.glitch&&fx.glitch>0){ctx.save();ctx.globalAlpha=fx.glitch;ctx.drawImage(d.glitch,fx.shift*-2,0,w,h);ctx.restore();}if(p>0&&p<1){ctx.fillStyle='#a5f0f92b';ctx.fillRect(w*edge-4,0,8,h);}}
  if(d.stage!=='off'){ctx.fillStyle='#102635bf';ctx.fillRect(12,12,180,24);ctx.fillStyle='#f5e4bf';ctx.font='12px sans-serif';ctx.fillText('Motor real · '+d.stage,20,28);}
 }
 stop(){if(this.awaiting){this.director.video.removeEventListener('loadeddata',this.awaiting);this.awaiting=null;}if(this.timer){clearInterval(this.timer);this.timer=null;}if(this.recorder?.state==='recording'){this.draw();this.recorder.stop();}}
}
